# Exact check over Q(sqrt2): (i) 2 qubits, group generated by H on either qubit and all 24 permutation
# matrices of the 4 basis states, orbit of |00>: are all single-qubit Z/X marginal expectations in {-1,0,1}?
# (ii) 3 qubits: H on qubits 1,2 then the exchange |110> <-> |111> (Toffoli) from |000>: target marginal.
from fractions import Fraction as F
from itertools import permutations, product
class Q2:
    __slots__=("p","q")
    def __init__(s,p,q=0): s.p=F(p); s.q=F(q)
    def __add__(s,o): return Q2(s.p+o.p,s.q+o.q)
    def __sub__(s,o): return Q2(s.p-o.p,s.q-o.q)
    def __mul__(s,o): return Q2(s.p*o.p+2*s.q*o.q, s.p*o.q+s.q*o.p)
    def __neg__(s): return Q2(-s.p,-s.q)
    def key(s): return (s.p,s.q)
    def __repr__(s): return f"{s.p}+{s.q}r2"
ZERO=Q2(0); R=Q2(0,F(1,2))  # 1/sqrt2
def apply_H(v,bit,n):
    out=[ZERO]*len(v)
    for i,a in enumerate(v):
        b=(i>>(n-1-bit))&1; j=i^(1<<(n-1-bit))
        if b==0: out[i]=out[i]+R*a; out[j]=out[j]+R*a
        else: out[j]=out[j]+R*a; out[i]=out[i]-R*a
    return out
def canon(v):
    k=tuple(x.key() for x in v)
    nk=tuple((-x).key() for x in v)
    return min(k,nk)
def zexp(v,bit,n):
    s=ZERO
    for i,a in enumerate(v):
        s = s + (a*a if ((i>>(n-1-bit))&1)==0 else -(a*a))
    return s.key()
def xexp(v,bit,n):
    w=apply_H(v,bit,n); return zexp(w,bit,n)
n=2; start=[Q2(1),ZERO,ZERO,ZERO]
perms=list(permutations(range(4)))
seen={canon(start):start}; frontier=[start]
while frontier:
    nf=[]
    for v in frontier:
        cands=[apply_H(v,0,n),apply_H(v,1,n)]+[[v[p.index(i)] for i in range(4)] for p in perms]
        for w in cands:
            c=canon(w)
            if c not in seen: seen[c]=w; nf.append(w)
    frontier=nf
vals=set()
for v in seen.values():
    for b in range(n): vals.add(zexp(v,b,n)); vals.add(xexp(v,b,n))
print("2-qubit orbit size (up to sign):",len(seen))
print("single-qubit Z/X expectations:",sorted(vals))
# (ii)
n=3; v=[Q2(1)]+[ZERO]*7
v=apply_H(v,0,n); v=apply_H(v,1,n)
v[6],v[7]=v[7],v[6]
p0=ZERO
for i,a in enumerate(v):
    if i&1==0: p0=p0+a*a
off=ZERO
for ab in range(4): off=off+v[2*ab]*v[2*ab+1]
print("3-qubit state:",v)
print("target P(0) =",p0," off-diagonal =",off)
